impl<'a, 'b> GraduateToMeteoraV1Cpi<'a, 'b> {
    pub fn new(
        program: &'b solana_program::account_info::AccountInfo<'a>,
        accounts: GraduateToMeteoraV1CpiAccounts<'a, 'b>,
        args: GraduateToMeteoraV1InstructionArgs,
    ) -> Self {
        Self {
            __program: program,
            genesis_account: accounts.genesis_account,
            bucket: accounts.bucket,
            bucket_token_account: accounts.bucket_token_account,
            mint: accounts.mint,
            payer: accounts.payer,
            authority: accounts.authority,
            fee_wallet: accounts.fee_wallet,
            pool: accounts.pool,
            config: accounts.config,
            lp_mint: accounts.lp_mint,
            token_b_mint: accounts.token_b_mint,
            a_vault: accounts.a_vault,
            b_vault: accounts.b_vault,
            a_token_vault: accounts.a_token_vault,
            b_token_vault: accounts.b_token_vault,
            a_vault_lp_mint: accounts.a_vault_lp_mint,
            b_vault_lp_mint: accounts.b_vault_lp_mint,
            a_vault_lp: accounts.a_vault_lp,
            b_vault_lp: accounts.b_vault_lp,
            payer_token_a: accounts.payer_token_a,
            payer_token_b: accounts.payer_token_b,
            payer_pool_lp: accounts.payer_pool_lp,
            protocol_token_a_fee: accounts.protocol_token_a_fee,
            protocol_token_b_fee: accounts.protocol_token_b_fee,
            rent: accounts.rent,
            mint_metadata: accounts.mint_metadata,
            native_sol: accounts.native_sol,
            meteora_program: accounts.meteora_program,
            metadata_program: accounts.metadata_program,
            vault_program: accounts.vault_program,
            token_program: accounts.token_program,
            associated_token_program: accounts.associated_token_program,
            system_program: accounts.system_program,
            backend_signer: accounts.backend_signer,
            __args: args,
        }
    }
    #[inline(always)]
    pub fn invoke(&self) -> solana_program::entrypoint::ProgramResult {
        self.invoke_signed_with_remaining_accounts(&[], &[])
    }
    #[inline(always)]
    pub fn invoke_with_remaining_accounts(
        &self,
        remaining_accounts: &[(
            &'b solana_program::account_info::AccountInfo<'a>,
            bool,
            bool,
        )],
    ) -> solana_program::entrypoint::ProgramResult {
        self.invoke_signed_with_remaining_accounts(&[], remaining_accounts)
    }
    #[inline(always)]
    pub fn invoke_signed(
        &self,
        signers_seeds: &[&[&[u8]]],
    ) -> solana_program::entrypoint::ProgramResult {
        self.invoke_signed_with_remaining_accounts(signers_seeds, &[])
    }
    #[allow(clippy::clone_on_copy)]
    #[allow(clippy::vec_init_then_push)]
    pub fn invoke_signed_with_remaining_accounts(
        &self,
        signers_seeds: &[&[&[u8]]],
        remaining_accounts: &[(
            &'b solana_program::account_info::AccountInfo<'a>,
            bool,
            bool,
        )],
    ) -> solana_program::entrypoint::ProgramResult {
        let mut accounts = Vec::with_capacity(34 + remaining_accounts.len());
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.genesis_account.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.bucket.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.bucket_token_account.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.mint.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.payer.key,
            true,
        ));
        if let Some(authority) = self.authority {
            accounts.push(solana_program::instruction::AccountMeta::new_readonly(
                *authority.key,
                true,
            ));
        } else {
            accounts.push(solana_program::instruction::AccountMeta::new_readonly(
                crate::GENESIS_PROGRAM_ID,
                false,
            ));
        }
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.fee_wallet.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.pool.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.config.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.lp_mint.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.token_b_mint.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.a_vault.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.b_vault.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.a_token_vault.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.b_token_vault.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.a_vault_lp_mint.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.b_vault_lp_mint.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.a_vault_lp.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.b_vault_lp.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.payer_token_a.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.payer_token_b.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.payer_pool_lp.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.protocol_token_a_fee.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.protocol_token_b_fee.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.rent.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.mint_metadata.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.native_sol.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.meteora_program.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.metadata_program.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.vault_program.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.token_program.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.associated_token_program.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.system_program.key,
            false,
        ));
        if let Some(backend_signer) = self.backend_signer {
            accounts.push(solana_program::instruction::AccountMeta::new_readonly(
                *backend_signer.key,
                true,
            ));
        } else {
            accounts.push(solana_program::instruction::AccountMeta::new_readonly(
                crate::GENESIS_PROGRAM_ID,
                false,
            ));
        }
        remaining_accounts.iter().for_each(|remaining_account| {
            accounts.push(solana_program::instruction::AccountMeta {
                pubkey: *remaining_account.0.key,
                is_writable: remaining_account.1,
                is_signer: remaining_account.2,
            })
        });
        let mut data = borsh::to_vec(&(GraduateToMeteoraV1InstructionData::new())).unwrap();
        let mut args = borsh::to_vec(&self.__args).unwrap();
        data.append(&mut args);

        let instruction = solana_program::instruction::Instruction {
            program_id: crate::GENESIS_PROGRAM_ID,
            accounts,
            data,
        };
        let mut account_infos = Vec::with_capacity(34 + 1 + remaining_accounts.len());
        account_infos.push(self.__program.clone());
        account_infos.push(self.genesis_account.clone());
        account_infos.push(self.bucket.clone());
        account_infos.push(self.bucket_token_account.clone());
        account_infos.push(self.mint.clone());
        account_infos.push(self.payer.clone());
        if let Some(authority) = self.authority {
            account_infos.push(authority.clone());
        }
        account_infos.push(self.fee_wallet.clone());
        account_infos.push(self.pool.clone());
        account_infos.push(self.config.clone());
        account_infos.push(self.lp_mint.clone());
        account_infos.push(self.token_b_mint.clone());
        account_infos.push(self.a_vault.clone());
        account_infos.push(self.b_vault.clone());
        account_infos.push(self.a_token_vault.clone());
        account_infos.push(self.b_token_vault.clone());
        account_infos.push(self.a_vault_lp_mint.clone());
        account_infos.push(self.b_vault_lp_mint.clone());
        account_infos.push(self.a_vault_lp.clone());
        account_infos.push(self.b_vault_lp.clone());
        account_infos.push(self.payer_token_a.clone());
        account_infos.push(self.payer_token_b.clone());
        account_infos.push(self.payer_pool_lp.clone());
        account_infos.push(self.protocol_token_a_fee.clone());
        account_infos.push(self.protocol_token_b_fee.clone());
        account_infos.push(self.rent.clone());
        account_infos.push(self.mint_metadata.clone());
        account_infos.push(self.native_sol.clone());
        account_infos.push(self.meteora_program.clone());
        account_infos.push(self.metadata_program.clone());
        account_infos.push(self.vault_program.clone());
        account_infos.push(self.token_program.clone());
        account_infos.push(self.associated_token_program.clone());
        account_infos.push(self.system_program.clone());
        if let Some(backend_signer) = self.backend_signer {
            account_infos.push(backend_signer.clone());
        }
        remaining_accounts
            .iter()
            .for_each(|remaining_account| account_infos.push(remaining_account.0.clone()));

        if signers_seeds.is_empty() {
            solana_program::program::invoke(&instruction, &account_infos)
        } else {
            solana_program::program::invoke_signed(&instruction, &account_infos, signers_seeds)
        }
    }
}

/// Instruction builder for `GraduateToMeteoraV1` via CPI.
///
/// ### Accounts:
///
///   0. `[writable]` genesis_account
///   1. `[writable]` bucket
///   2. `[writable]` bucket_token_account
///   3. `[]` mint
///   4. `[writable, signer]` payer
///   5. `[signer, optional]` authority
///   6. `[writable]` fee_wallet
///   7. `[writable]` pool
///   8. `[]` config
///   9. `[writable]` lp_mint
///   10. `[]` token_b_mint
///   11. `[writable]` a_vault
///   12. `[writable]` b_vault
///   13. `[writable]` a_token_vault
///   14. `[writable]` b_token_vault
///   15. `[writable]` a_vault_lp_mint
///   16. `[writable]` b_vault_lp_mint
///   17. `[writable]` a_vault_lp
